from collections import defaultdict
def f(gi):
    h,w=len(gi),len(gi[0])
    pts=[(i,j,gi[i][j]) for i in range(h) for j in range(w) if gi[i][j]!=2]
    d=defaultdict(list)
    for p in pts: d[p[2]].append((p[0],p[1]))
    out=[[2]*w for _ in range(h)]
    for c,ps in d.items():
        (i1,j1),(i2,j2)=min(ps),max(ps)
        for i in range(min(i1,i2),max(i1,i2)+1):
            for j in range(min(j1,j2),max(j1,j2)+1):
                out[i][j]=c
    return out
